package com.nora.tunnel.ui.screens.statistics import androidx.compose.foundation.layout.* import androidx.compose.foundation.lazy.LazyColumn import androidx.compose.foundation.lazy.items import androidx.compose.material3.* import androidx.compose.runtime.Composable import androidx.compose.ui.Modifier import androidx.compose.ui.unit.dp @Composable fun HistoryScreen(sessions: List<com.nora.tunnel.data.database.ConnectionSession>, onClear: ()->Unit) { Column(Modifier.fillMaxSize().padding(16.dp)) { Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) { Text("Connection History", style = MaterialTheme.typography.headlineSmall) TextButton(onClick = onClear){ Text("Clear all") } } if(sessions.isEmpty()) { Text("No history yet.", modifier = Modifier.padding(top=32.dp)) return } LazyColumn { items(sessions) { s -> Card(Modifier.fillMaxWidth().padding(vertical=4.dp)) { ListItem( headlineContent = { Text(s.protocol) }, supportingContent = { Text("${formatTime(s.startTime)} • ${s.durationMs?.let { "${it/1000}s" } ?: "--"} • ${s.rxBytes+s.txBytes} bytes") }, trailingContent = { Text(s.result, color = if(s.result=="Successful") MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.error) } ) } } } } } private fun formatTime(t: Long) = java.text.SimpleDateFormat("HH:mm:ss").format(java.util.Date(t))
